<script setup>
import { computed, ref, watch } from 'vue'
import { gamerHighlights, GAMER_PLATFORMS } from '@/services/gamerIdentity'
const props = defineProps({ identities: { type: Array, default: () => [] }, own: Boolean, loading: Boolean, error: String, showRecent: Boolean, actionLabel: { type: String, default: 'Conectar sistemas' }, showLink: { type: Boolean, default: true } })
defineEmits(['open'])
const connected = computed(() => props.identities.filter(identity => GAMER_PLATFORMS[identity.platform] && identity.connectionState === 'connected' && (props.own || identity.visibility === 'public')))
const platforms = computed(() => [...new Set(connected.value.map(identity => identity.platform))])
const selectedPlatform = ref('')
watch(platforms, values => { if (!values.includes(selectedPlatform.value)) selectedPlatform.value = values.includes('nintendo') ? 'nintendo' : values[0] || '' }, { immediate: true })
const selectedIdentities = computed(() => connected.value.filter(identity => identity.platform === selectedPlatform.value))
const highlights = computed(() => gamerHighlights(selectedIdentities.value, props.own))
const recent = computed(() => props.showRecent ? selectedIdentities.value.filter(identity => identity.connectionState==='connected' && (props.own || identity.visibility==='public')).flatMap(identity => identity.history || []).filter(entry => entry.game?.title && Number.isFinite(Date.parse(entry.at))).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).slice(0,3) : [])
const xboxAchievements = computed(() => selectedIdentities.value.flatMap(identity => identity.gameAchievements || []).filter(entry => entry.game?.title).slice(0,3))
const achievementSlots = computed(() => Array.from({length:3},(_,index)=>xboxAchievements.value[index] || null))
const playedSlots = computed(() => Array.from({length:3},(_,index)=>highlights.value.mostPlayed[index] || null))
const recentSlots = computed(() => Array.from({length:3},(_,index)=>recent.value[index] || null))
const dateLabel = value => new Intl.DateTimeFormat('es-ES', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
const number = value => new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2, useGrouping: false }).format(value)
const hoursLabel = minutes => {
 const hours = Math.floor(minutes / 60), remainder = minutes % 60
 return hours ? `${number(hours)} h${remainder ? ` ${number(remainder)} min` : ''}` : `${number(remainder)} min`
}
</script>
<template>
 <section v-if="own || highlights.platforms.length" class="profile-gamer-preview" aria-label="Mi universo gamer">
  <header class="gamer-heading"><h2><i class="fas fa-gamepad" aria-hidden="true"></i> Mi universo gamer</h2><div class="gamer-heading-actions"><div v-if="platforms.length > 1" class="gamer-system-selector" role="group" aria-label="Sistema de juego"><button v-for="platform in platforms" :key="platform" type="button" :aria-pressed="selectedPlatform === platform" @click="selectedPlatform = platform">{{ platform === 'nintendo' ? 'Nintendo' : GAMER_PLATFORMS[platform] }}</button></div><button v-if="showLink" class="gamer-connect-button" type="button" @click="$emit('open')"><i class="fas fa-plug" aria-hidden="true"></i>{{ actionLabel }}</button></div></header>
  <p v-if="loading" role="status" class="gamer-invitation">Consultando plataformas…</p><p v-if="error" role="status" class="gamer-invitation">{{ error }}</p>
  <p v-if="!highlights.platforms.length" class="gamer-invitation">Conecta Nintendo o Xbox para compartir tu actividad de juego.</p>
  <template v-else>
   <article v-if="highlights.activity" class="gamer-featured">
    <img v-if="highlights.activity.game.imageUrl" class="featured-backdrop" :src="highlights.activity.game.imageUrl" alt="" aria-hidden="true" loading="lazy" />
    <div class="featured-shade" aria-hidden="true"></div>
    <img v-if="highlights.activity.game.imageUrl" class="featured-cover" :src="highlights.activity.game.imageUrl" alt="" loading="lazy" /><div v-else class="featured-placeholder" aria-hidden="true"><i class="fas fa-gamepad"></i></div>
    <div class="featured-info"><span class="gamer-presence" :class="{playing:highlights.activity.playing}"><span class="presence-dot" aria-hidden="true"></span>{{ highlights.activity.playing ? 'Jugando ahora' : 'Último juego detectado' }}</span><h3 :title="highlights.activity.game.title">{{ highlights.activity.game.title }}</h3><span class="featured-platform">{{ highlights.activity.platform }}</span><time v-if="highlights.activity.at" :datetime="highlights.activity.at"><i class="far fa-clock" aria-hidden="true"></i> Última actividad: {{ dateLabel(highlights.activity.at) }}</time><span v-else class="featured-time-empty">Fecha no disponible</span></div>
   </article>
   <article v-else class="gamer-featured featured-empty"><div class="featured-placeholder" aria-hidden="true"><i class="fas fa-gamepad"></i></div><div class="featured-info"><span class="gamer-presence">Actividad de juego</span><h3>Sin actividad disponible</h3><span class="featured-platform">{{ highlights.platforms[0] }}</span><span class="featured-time-empty">La fuente no publica un juego.</span></div></article>
   <div v-if="selectedPlatform === 'xbox'" class="gamer-game-achievements"><h3 class="gamer-section-title">Logros por juego</h3><ul><li v-for="(entry,index) in achievementSlots" :key="entry?.game.id || 'achievement-empty-'+index" :class="{'empty-game':!entry}"><div class="achievement-art"><img v-if="entry?.game.imageUrl" :src="entry.game.imageUrl" alt="" loading="lazy"/><i v-else class="fas fa-trophy" aria-hidden="true"></i></div><div class="game-achievement-copy"><template v-if="entry"><strong :title="entry.game.title">{{ entry.game.title }}</strong><span>{{ entry.unlocked !== null ? number(entry.unlocked) + ' logros desbloqueados' : 'Logros no disponibles' }}</span><span>{{ entry.gamerscore !== null ? number(entry.gamerscore) + (entry.totalGamerscore !== null ? ' / ' + number(entry.totalGamerscore) : '') + ' G' : 'Gamerscore no disponible' }}</span><div class="game-progress"><template v-if="entry.progress !== null"><label :for="'xbox-progress-'+index">Progreso Xbox · {{ number(entry.progress) }} %</label><progress :id="'xbox-progress-'+index" :value="entry.progress" max="100">{{ entry.progress }} %</progress></template><span v-else>Progreso no disponible</span></div><small v-if="entry.remaining !== null">Faltan {{ number(entry.remaining) }} logros</small><small v-else>Total de logros no disponible</small><small v-if="entry.remainingGamerscore !== null">Faltan {{ number(entry.remainingGamerscore) }} G</small></template><template v-else><strong>Sin datos de logros</strong><span>Xbox no publica este progreso.</span></template></div></li></ul></div>
   <div v-else class="gamer-most-played"><h3 class="gamer-section-title">Más jugados</h3><ol><li v-for="(entry,index) in playedSlots" :key="entry?.key || 'empty-'+index" :class="{'empty-game':!entry}"><div class="played-art"><img v-if="entry?.game.imageUrl" :src="entry.game.imageUrl" alt="" loading="lazy" /><i v-else class="fas fa-gamepad cover-placeholder" aria-hidden="true"></i><span v-if="entry" class="played-rank" aria-hidden="true">{{ index+1 }}</span></div><div v-if="entry" class="played-copy"><strong :title="entry.game.title">{{ entry.game.title }}</strong><span class="played-hours">{{ hoursLabel(entry.minutes) }}</span><small>{{ entry.platform }}</small></div><div v-else class="played-copy empty-copy"><strong>Sin datos de juego</strong><span>Aún no disponible.</span></div></li></ol></div>
   <div v-if="showRecent" class="gamer-recent-preview"><h3 class="gamer-section-title">Actividad reciente</h3><ul><li v-for="(entry,index) in recentSlots" :key="entry?.game.id || 'recent-empty-'+index" :class="{'empty-game':!entry}"><img v-if="entry?.game.imageUrl" :src="entry.game.imageUrl" alt="" loading="lazy" /><i v-else class="fas fa-gamepad cover-placeholder" aria-hidden="true"></i><div class="recent-shade" aria-hidden="true"></div><div v-if="entry" class="recent-copy"><strong :title="entry.game.title">{{ entry.game.title }}</strong><time :datetime="entry.at">{{ dateLabel(entry.at) }}</time></div><div v-else class="recent-copy empty-copy"><strong>Sin actividad publicada</strong><span>No hay datos disponibles.</span></div></li></ul></div>
   <ul class="gamer-connected" aria-label="Plataformas conectadas"><li v-for="platform in highlights.platforms" :key="platform"><span aria-hidden="true">●</span> {{ platform }}</li></ul>
  </template>
 </section>
</template>
